CyberNative-DPO_go_10,10,-1,[{""role"": ""user"", ""content"": ""Write a go code that uses a mutex to safely increment a counter in parallel. The program should create 1000 goroutines, each of which increments a shared counter. After all goroutines have finished, print the final value of the counter.""}]","[{""role"": ""assistant"", ""content"": ""```go
package main

import (
	""fmt""
	""sync""
)

type Counter struct {
	mu    sync.RWMutex
	count int
}

func (c *Counter) Increment() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.count++
}

func (c *Counter) Value() int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.count
}

func main() {
	var wg sync.WaitGroup
	var counter Counter

	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			counter.Increment()
		}()
	}

	wg.Wait()
	fmt.Println(counter.Value())
}
```""}]","

