CyberNative-DPO_go_29,29,-1,[{""role"": ""user"", ""content"": ""Write a go code that creates a thread-safe map where multiple goroutines can concurrently read and write data. The map should be created using a constructor function `NewSafeMap`. It should have two methods `Set` and `Get` which allow setting and getting values from the map respectively. The `Set` method should lock the map while writing and `Get` should lock the map while reading. In the `main` function, create 10 goroutines that will set values in the map with keys ""key0"" to ""key9"" and corresponding values ""value0"" to ""value9"". Then create another 10 goroutines that will get these values from the map and print them. Use `sync.WaitGroup` to wait for all goroutines to finish.""}]","[{""role"": ""assistant"", ""content"": ""```go
package main

import (
	""fmt""
	""sync""
)

type SafeMap struct {
	sync.RWMutex
	data map[string]string
}

func NewSafeMap() *SafeMap {
	return &SafeMap{
		data: make(map[string]string),
	}
}

func (m *SafeMap) Set(key string, value string) {
	m.Lock()
	defer m.Unlock()
	m.data[key] = value
}

func (m *SafeMap) Get(key string) (string, bool) {
	m.RLock()
	defer m.RUnlock()
	value, ok := m.data[key]
	return value, ok
}

func main() {
	m := NewSafeMap()

	var wg sync.WaitGroup
