	c.Lock()
	defer c.Unlock()
	c.value++
}

func (c *Counter) Decrement() {
	c.Lock()
	defer c.Unlock()
	c.value--
}

func (c *Counter) Value() int {
	c.Lock()
	defer c.Unlock()
	return c.value
}

